class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = [i for i in range(1, n + 1) if i % 2 == 1]
        evens = [i for i in range(1, n + 1) if i % 2 == 0]
        no, ne = len(odds), len(evens)

        if abs(no - ne) > 1:
            return []

        # Count alternating permutations starting with parity p (1=odd, 0=even)
        # using co odd-count and ce even-count remaining.
        def count(co, ce, p):
            if p == 1:
                if co == 0:
                    return 0
                if not (co == ce or co == ce + 1):
                    return 0
                return factorial(co - 1) * factorial(ce)
            else:
                if ce == 0:
                    return 0
                if not (ce == co or ce == co + 1):
                    return 0
                return factorial(ce - 1) * factorial(co)

        # Determine valid starting parities
        start_parities = []
        if no == ne:
            start_parities = [1, 0]
        elif no == ne + 1:
            start_parities = [1]
        else:
            start_parities = [0]

        total = sum(count(no, ne, p) for p in start_parities)
        if k > total:
            return []

        res = []
        prev = -1  # -1 means no previous element yet
        idx = k
        for _ in range(n):
            if prev == -1:
                candidates = sorted(odds + evens)
            elif prev == 1:
                candidates = evens
            else:
                candidates = odds

            for x in candidates:
                p = x % 2
                if prev == -1:
                    c = count(no, ne, p)
                else:
                    if p == 1:
                        c = factorial(no - 1) * factorial(ne)
                    else:
                        c = factorial(ne - 1) * factorial(no)

                if idx > c:
                    idx -= c
                else:
                    res.append(x)
                    if p == 1:
                        odds.remove(x)
                        no -= 1
                    else:
                        evens.remove(x)
                        ne -= 1
                    prev = p
                    break

        return res

