    for i in range(N):
        for j, c in edges[i]:
            if dist[i][j] > 1:
                dist[i][j] = 1
                dq.append((i, j))

    # BFS: expand palindrome by adding same letter at both ends
    # If we have palindrome from u to v with length d,
    # and edges a->u with label c, v->b with label c,
    # then a to b has palindrome of length d+2
    while dq:
        u, v = dq.popleft()
        d = dist[u][v]
        for a, c1 in [(x, c) for x in range(N) for y, c in edges[x] if y == u]:
            pass
        # More efficient: precompute reverse edges
        # We'll do it inline below instead
        break

    # Reset and redo with precomputed reverse adjacency
    dist = [[INF] * N for _ in range(N)]
    dq = deque()

    # rev_edges[v] = list of (u, label) meaning edge u->v
    rev_edges = [[] for _ in range(N)]
    for i in range(N):
        for j, c in edges[i]:
            rev_edges[j].append((i, c))

    for i in range(N):
