        u, v = dq.popleft()
        d = dist[u][v]
        # prepend edge a->u with label c, append edge v->b with label c
        for a, c1 in rev_edges[u]:
            for b, c2 in edges[v]:
                if c1 == c2 and dist[a][b] == INF:
