class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        # Split pattern into three literal parts
        star1 = p.index('*')
        star2 = p.index('*', star1 + 1)
        a = p[:star1]
        b = p[star1 + 1:star2]
        c = p[star2 + 1:]
        la, lb, lc = len(a), len(b), len(c)

        def z_array(t: str):
            m = len(t)
            z = [0] * m
            l = r = 0
            for i in range(1, m):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < m and t[z[i]] == t[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l, r = i, i + z[i] - 1
            return z

        def match_positions(pat: str):
            # returns list of start indices in s where pat matches
            m = len(pat)
            if m == 0:
                return list(range(n + 1))
            if m > n:
                return []
            t = pat + '#' + s
            z = z_array(t)
            res = []
            for i in range(m + 1, len(t)):
                if z[i] >= m:
                    res.append(i - m - 1)
            return res

        A = match_positions(a)  # start positions of a
        B = match_positions(b)  # start positions of b
        C = match_positions(c)  # start positions of c

        if not A or not B or not C:
            return -1

        import bisect
        ans = float('inf')
        # For each occurrence of b, find latest a ending <= b_start,
        # and earliest c starting >= b_end.
        for j in B:
            # a must satisfy i + la <= j  => i <= j - la
            ia = bisect.bisect_right(A, j - la) - 1
            if ia < 0:
                continue
            i = A[ia]
            # c must satisfy k >= j + lb
            ic = bisect.bisect_left(C, j + lb)
            if ic == len(C):
                continue
            k = C[ic]
            length = k + lc - i
            if length < ans:
                ans = length

        return -1 if ans == float('inf') else ans

