MOD = 998244353

def main():
    W, H, L, R, D, U = map(int, sys.stdin.readline().split())
    N = W + H + 5
    fac = [1] * (N + 1)
    for i in range(1, N + 1):
        fac[i] = fac[i - 1] * i % MOD
    invfac = [1] * (N + 1)
    invfac[N] = pow(fac[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfac[i - 1] = invfac[i] * i % MOD

    def C(n, k):
        if k < 0 or k > n or n < 0:
            return 0
        return fac[n] * invfac[k] % MOD * invfac[n - k] % MOD

    def paths(x1, y1, x2, y2):
        if x2 < x1 or y2 < y1:
            return 0
        return C(x2 - x1 + y2 - y1, x2 - x1)

    def rect(x1, y1, x2, y2):
        if x1 > x2 or y1 > y2:
            return 0
        return paths(x1, y1, x2 + 1, y2 + 1)

    ans = 0
    # Bottom strip: 0<=x<=W, 0<=y<=D-1
    ans = (ans + rect(0, 0, W, D - 1)) % MOD
    # Top strip: 0<=x<=W, U+1<=y<=H
    ans = (ans + rect(0, U + 1, W, H)) % MOD
    # Left strip: 0<=x<=L-1, D<=y<=U
    ans = (ans + rect(0, D, L - 1, U)) % MOD
    # Right strip: R+1<=x<=W, D<=y<=U
    ans = (ans + rect(R + 1, D, W, U)) % MOD

    # Cross terms: bottom -> left
    if D >= 1 and L >= 1:
        s = 0
        for x in range(L):
            s = (s + paths(x, D - 1, L, U + 1)) % MOD
        ans = (ans + rect(0, 0, W, D - 2) * s) % MOD
    # bottom -> right
    if D >= 1 and R < W:
        s = 0
        for x in range(R + 1, W + 1):
            s = (s + paths(x, D - 1, W + 1, U + 1)) % MOD
        ans = (ans + rect(0, 0, W, D - 2) * s) % MOD
    # left -> top
    if L >= 1 and U < H:
        s = 0
        for y in range(D, U + 1):
            s = (s + paths(L - 1, y, W + 1, U + 1)) % MOD
        ans = (ans + rect(0, D, L - 2, U) * s) % MOD
    # right -> top
    if R < W and U < H:
        s = 0
        for y in range(D, U + 1):
            s = (s + paths(W, y, W + 1, U + 1)) % MOD
        ans = (ans + rect(R + 1, D, W, U) * s) % MOD

    print(ans % MOD)

