class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # We need to choose k positions out of n-1 for equal adjacent pairs
        # First element: m choices
        # For each of the n-1 transitions: if equal (k of them), 1 choice; if different (n-1-k of them), m-1 choices
        # Answer = C(n-1, k) * m * (m-1)^(n-1-k) mod MOD

        # Compute factorials and inverse factorials for combination
        max_n = n
        fact = [1] * (max_n + 1)
        for i in range(1, max_n + 1):
            fact[i] = fact[i - 1] * i % MOD

        def mod_pow(base, exp, mod):
            result = 1
            base %= mod
            while exp > 0:
                if exp & 1:
                    result = result * base % mod
                base = base * base % mod
                exp >>= 1
            return result

        def inv(x):
            return mod_pow(x, MOD - 2, MOD)

        def comb(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * inv(fact[r]) % MOD * inv(fact[n - r]) % MOD

        result = comb(n - 1, k)
        result = result * m % MOD
        result = result * mod_pow(m - 1, n - 1 - k, MOD) % MOD

        return result

