class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        cnt = [0] * 26
        for c in s:
            cnt[ord(c) - ord('a')] += 1

        n = len(s)
        ans = float('inf')

        # Try each possible target frequency
        for target in range(1, n + 1):
            # dp[i][j] = min cost considering first i+1 letters (0..i), 
            # where j = number of characters carried over from letter i to letter i+1
            # We use a dictionary for sparse states
            dp = {0: 0}

            for i in range(26):
                new_dp = {}
                for carry, cost in dp.items():
                    # Current count at letter i includes carried characters from i-1
                    cur = cnt[i] + carry

                    # Option 1: Make letter i have exactly `target` occurrences
                    if cur >= target:
                        # Delete (cur - target) characters
                        c1 = cost + (cur - target)
                        if 0 not in new_dp or c1 < new_dp[0]:
                            new_dp[0] = c1
                    else:
                        # Need (target - cur) more: insert them
                        c1 = cost + (target - cur)
                        if 0 not in new_dp or c1 < new_dp[0]:
                            new_dp[0] = c1

                    # Option 2: Delete all characters at letter i (frequency 0)
                    c2 = cost + cur
                    if 0 not in new_dp or c2 < new_dp[0]:
                        new_dp[0] = c2

                    # Option 3: Change some characters to letter i+1 (only if i < 25)
                    if i < 25:
                        # Change k characters from i to i+1, where 0 <= k <= cur
                        # After changing, letter i has (cur - k) occurrences
                        # We want (cur - k) to be either 0 or target

                        # Sub-option 3a: letter i ends with `target` occurrences
                        if cur >= target:
                            k = cur - target
                            c3 = cost + k  # k change operations
                            if k not in new_dp or c3 < new_dp[k]:
                                new_dp[k] = c3

                        # Sub-option 3b: letter i ends with 0 occurrences (change all)
                        k = cur
                        c4 = cost + k
                        if k not in new_dp or c4 < new_dp[k]:
                            new_dp[k] = c4

                dp = new_dp

            # After processing all 26 letters, any carry from 'z' must be deleted
            for carry, cost in dp.items():
                total = cost + carry
                ans = min(ans, total)

        return ans

