class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # Map each value to its index (values are unique)
        idx = {v: i for i, v in enumerate(nums)}

        # For each possible lcm value m <= threshold, connect all pairs
        # of array elements that both divide m.
        # We iterate over multiples: for each number x present in nums,
        # look at multiples m = x, 2x, 3x, ... <= threshold.
        # For each such m, x is a divisor of m. We collect, for each m,
        # the list of present divisors, and union them together.
        #
        # To do this efficiently, we build divisor -> index mapping and
        # for each m gather divisors by iterating over present numbers'
        # multiples. Equivalent: for each m, find which present numbers divide m.
        # Instead, iterate over each present number x and add its index to
        # buckets[m] for all multiples m of x up to threshold.
        buckets = [[] for _ in range(threshold + 1)]
        for v, i in idx.items():
            if v > threshold:
                # x can still connect if lcm(x, y) <= threshold; since lcm >= x,
                # if x > threshold it can never connect. Skip.
                continue
            for m in range(v, threshold + 1, v):
                buckets[m].append(i)

        for m in range(1, threshold + 1):
            lst = buckets[m]
            if len(lst) > 1:
                first = lst[0]
                for other in lst[1:]:
                    union(first, other)

        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
